      "rank": 1,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made the interaction of individual microwave photons and artificial atoms a precise, controllable physical regime, with deep consequences for quantum optics.",
        "attribution": "Blais supplied a defining theoretical framework, while Wallraff and Schoelkopf established its decisive experimental realization; the broader intellectual credit is necessarily distributed.",
        "maturity": "The phenomena and architecture have been repeatedly reproduced and form a mature experimental field.",
        "uncertainties": [
          "The line between foundational circuit-QED work and closely related superconducting-circuit advances already recognized by the Prize requires careful delimitation."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Peter W. Shor",
        "Alexei Kitaev",
        "Andrew M. Steane"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault tolerance identified how fragile quantum states can support scalable computation, a profound conceptual transformation in quantum physics.",
        "attribution": "Shor, Kitaev, and Steane made distinct foundational contributions to codes, fault tolerance, and topological protection.",
        "maturity": "The theoretical result is exceptionally mature and experimental demonstrations increasingly test its central premises.",
        "uncertainties": [
          "Fully fault-tolerant computation at useful scale has not yet been conclusively achieved.",
          "The broad field contains further contributors whose treatment would need scrutiny."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provided an unusually clean and controllable realization of quantum computation and simulation, making abstract quantum-information ideas experimentally tangible.",
        "attribution": "Cirac and Zoller supplied seminal proposals and Blatt helped establish the powerful experimental platform; their roles are complementary and identifiable.",
        "maturity": "High-fidelity control, entanglement, simulation, and independent implementations establish remarkable maturity.",
        "uncertainties": [
          "A prize would need distinguish the platform's foundational physics from the wider multi-platform race toward quantum computing."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision measurement by reaching extraordinary accuracy while controlling large ensembles of atoms.",
        "attribution": "Katori pioneered the magic-wavelength lattice-clock concept and Ye made central experimental advances toward its highest performance.",
        "maturity": "Independent laboratories have demonstrated and extended the method to the stated precision regime.",
        "uncertainties": [
          "The exact allocation between original clock concepts and subsequent metrological advances needs careful historical assessment."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Yakir Aharonov",
        "Michael Berry"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric and topological phases exposed a fundamental nonlocal and geometrical structure of quantum mechanics that now permeates modern physics.",
        "attribution": "Aharonov and Berry are clearly associated with landmark formulations, although the two effects arose in different contexts.",
        "maturity": "Both effects are long established experimentally and conceptually, with far-reaching influence.",
        "uncertainties": [
          "Combining the Aharonov-Bohm and Berry phases in one citation may obscure their distinct historical origins and additional contributors."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Jörg Wrachtrup",
        "Fedor Jelezko",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Coherent single-spin control in diamond made a solid-state quantum system into an exceptional probe of fields and local environments.",
        "attribution": "Wrachtrup and Jelezko were central to experimental single-defect spin control, while Lukin made major contributions to the quantum-information use of such systems.",
        "maturity": "The capabilities are robust, broadly reproduced, and used in quantum sensing and quantum-optics research.",
        "uncertainties": [
          "The discovery overlaps substantially with the broader optical-interface candidate and requires a sharp attribution boundary."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices gave physicists an exceptionally controllable quantum simulator for strongly correlated many-body matter.",
        "attribution": "Zoller helped establish the theoretical programme, while Bloch and Greiner led seminal experimental realizations; the candidate's full history is wider than three people.",
        "maturity": "The platform has produced extensive, reproducible many-body physics across laboratories.",
        "uncertainties": [
          "Whether quantum simulation itself constitutes one sufficiently bounded discovery, and the allocation among many pioneers, remains difficult."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Markus Aspelmeyer",
        "Oskar Painter",
        "Andrew N. Cleland"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics brought mechanical motion into the quantum domain and enabled exquisitely controlled light-matter experiments at macroscopic scales.",
        "attribution": "Aspelmeyer, Painter, and Cleland each made identifiable pioneering contributions to quantum optomechanics and mechanical quantum control.",
        "maturity": "Quantum control of mechanical systems has been achieved repeatedly with varied architectures and has become a vigorous mature field.",
        "uncertainties": [
          "The credit landscape also includes important theoretical and experimental contributors not represented in the proposed trio."
        ]
      }
    }
  ]
